","import React from "react";
import { Icon } from "../Icons";

export function FilterSelect({ label, value, options, onChange, active }:
 { label: string; value: string; options: string[]; onChange: (v: string) => void; active: boolean }) {
 const [open, setOpen] = React.useState(false);
 const ref = React.useRef<HTMLDivElement>(null);
 React.useEffect(() => {
 const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };
 document.addEventListener("mousedown", h);
 return () => document.removeEventListener("mousedown", h);
 }, []);
 return (
 <div className={`ci-filter ${active ? "ci-filter--active" : ""}`} ref={ref}
 onClick={() => setOpen(o => !o)} role="button" tabIndex={0}>
 <span className="ci-filter__k">{label}</span>
 <span className="ci-filter__v">{value}</span>
 <Icon.chevronD className="ci-filter__chev" style={{ width: 13, height: 13 }} />
 {open && (
 <div className="ci-filter__menu" onClick={e => e.stopPropagation()}>
 {options.map(o => (
 <div key={o} className={`ci-filter__opt ${o === value ? "ci-filter__opt--sel" : ""}`}
 onClick={() => { onChange(o); setOpen(false); }}>
 {o === value && <Icon.target style={{ width: 12, height: 12 }} />}
 <span style={{ marginLeft: o === value ? 0 : 20 }}>{o}</span>
 </div>
 ))}
 </div>
 )}
 </div>
 );
}
","// Champion Intelligence — realistic demo data (placeholder, POV/POC)

export type Stage =
 | "Early Talent" | "Youth" | "University" | "Amateur"
 | "Club" | "Elite" | "Talent Transfer" | "Paralympic" | "Community";

export type Status = "green" | "amber" | "red" | "cyan";

export interface Athlete {
 id: string;
 name: string;
 sport: string;
 region: string;
 age: number;
 gender: "M" | "F";
 stage: Stage;
 pathway: string;
 source: string;
 potential: number; // 0-100 champion potential index (CPI)
 readiness: number; // 0-100 physical readiness
 momentum: number; // -100..100 trajectory delta
 injuryRisk: number; // 0-100
 benchmark: number; // percentile vs national cohort
 status: Status;
 wearable: number; // recovery %
 vision: number; // biomechanics score
 flag?: string;
}

export const SPORTS = ["Athletics", "Swimming", "Cycling", "Rowing", "Judo", "Gymnastics", "Basketball", "Para-Athletics"];
export const REGIONS = ["North", "South", "East", "West", "Central", "Coastal", "Highlands", "Metro"];
export const STAGES: Stage[] = ["Early Talent", "Youth", "University", "Amateur", "Club", "Elite", "Talent Transfer", "Paralympic", "Community"];
export const PATHWAYS = ["Podium", "Progression", "Foundation", "Transfer", "Para Pathway", "Discovery"];
export const SOURCES = ["Digital Assessment", "School Screening", "Club Referral", "Self-Nomination", "Scout Network", "Transfer Program"];
export const COMP_LEVELS = ["Grassroots", "Regional", "National", "International", "Elite/Podium"];

const AV = ["#35e0ff", "#34e3a4", "#ffc24b", "#9a7bff", "#4d8dff", "#2fe6c4", "#ff8fa3"];
export const avatarColor = (i: number) => AV[i % AV.length];
export const initials = (n: string) => n.split(" ").map(w => w[0]).slice(0, 2).join("").toUpperCase();

const NAMES = [
 "Aria Nakamura", "Liam Okafor", "Sofia Andersen", "Kai Mensah", "Nora Bianchi",
 "Diego Ferreira", "Mia Kowalski", "Elias Vance", "Zara Haddad", "Noah Lindqvist",
 "Priya Raman", "Marco Duval", "Yuki Tanaka", "Ines Costa", "Ravi Shah",
 "Amara Diallo", "Theo Larsen", "Lena Novak", "Omar Farouk", "Chloe Beaumont",
 "Jonas Weber", "Aisha Rahman", "Felix Moreau", "Tara Vasquez", "Sven Berg",
 "Nadia Petrov", "Hugo Silva", "Maya Lindgren", "Idris Bello", "Emilia Rossi"];

function rng(seed: number) { let s = seed; return () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff; }

export const ATHLETES: Athlete[] = NAMES.map((name, i) => {
 const r = rng(i * 97 + 7);
 const potential = Math.round(58 + r() * 40);
 const injuryRisk = Math.round(r() * 70);
 const momentum = Math.round((r() - 0.35) * 80);
 const status: Status = injuryRisk > 62 ? "red" : injuryRisk > 42 ? "amber" : potential > 88 ? "cyan" : "green";
 const stage = STAGES[Math.floor(r() * STAGES.length)];
 return {
 id: "ATH-" + (1024 + i),
 name,
 sport: SPORTS[Math.floor(r() * SPORTS.length)],
 region: REGIONS[Math.floor(r() * REGIONS.length)],
 age: Math.round(11 + r() * 21),
 gender: r() > 0.5 ? "F" : "M",
 stage,
 pathway: PATHWAYS[Math.floor(r() * PATHWAYS.length)],
 source: SOURCES[Math.floor(r() * SOURCES.length)],
 potential,
 readiness: Math.round(60 + r() * 38),
 momentum,
 injuryRisk,
 benchmark: Math.round(40 + r() * 59),
 status,
 wearable: Math.round(55 + r() * 44),
 vision: Math.round(62 + r() * 36),
 flag: injuryRisk > 62 ? "Load spike detected" : potential > 90 ? "Breakout trajectory" : momentum < -20 ? "Momentum decline" : undefined,
 };
});

// KPI series for command center
export interface Kpi {
 id: string; label: string; value: number; unit?: string;
 delta: number; status: Status; benchmark?: string;
 spark: number[]; icon: string;
}

const spark = (seed: number, n = 16) => { const r = rng(seed); let v = 40 + r() * 20; return Array.from({ length: n }, () => (v = Math.max(8, Math.min(95, v + (r() - 0.45) * 16)))); };

export const COMMAND_KPIS: Kpi[] = [
 { id: "pool", label: "Talent Pool Tracked", value: 48213, delta: 6.4, status: "cyan", benchmark: "Target 50k", spark: spark(3), icon: "users" },
 { id: "champions", label: "Projected Champions", value: 187, delta: 12.1, status: "green", benchmark: "vs 167 LY", spark: spark(11), icon: "star" },
 { id: "watch", label: "High-Potential Watchlist", value: 642, delta: 3.2, status: "cyan", benchmark: "P90+ CPI", spark: spark(21), icon: "radar" },
 { id: "risk", label: "Athletes At Risk", value: 73, delta: 8.9, status: "amber", benchmark: "Injury/dropout", spark: spark(31), icon: "alert" },
 { id: "transfer", label: "Talent Transfers", value: 29, delta: 21.0, status: "green", benchmark: "Cross-sport", spark: spark(41), icon: "shuffle" },
 { id: "interventions", label: "Active Interventions", value: 214, delta: -4.1, status: "green", benchmark: "84% on-track", spark: spark(51), icon: "activity" },
];

// Talent funnel (population → champion)
export const FUNNEL = [
