export function RisksRow() {
 const { open, setLinkedAction, linkedAction } = useCmd();
 const order = { CRITICAL: 0, HIGH: 1, MEDIUM: 2 } as const;
 const sorted = [...RISKS].sort((a, b) => order[a.sev] - order[b.sev]);
 const counts = { CRITICAL: RISKS.filter(r => r.sev === "CRITICAL").length, HIGH: RISKS.filter(r => r.sev === "HIGH").length, MEDIUM: RISKS.filter(r => r.sev === "MEDIUM").length };
 return (
 <Panel span={7} hover title="Requires Attention"
 sub="Detected problems · click to see the linked action on the right"
 right={<div style={{ display: "flex", gap: 6 }}>
 <span className="cc-risk__sev cc-sev--CRITICAL">{counts.CRITICAL} CRIT</span>
 <span className="cc-risk__sev cc-sev--HIGH">{counts.HIGH} HIGH</span>
 <span className="cc-risk__sev cc-sev--MEDIUM">{counts.MEDIUM} MED</span>
 </div>}>
 <div style={{ display: "flex", gap: 14 }}>
 <div style={{ flex: 1.5, minWidth: 0, display: "flex", flexDirection: "column", gap: 6 }}>
 {sorted.map(r => (
 <div key={r.id} className="cc-risk" onClick={() => { setLinkedAction(r.link || null); open("risk", r); }}
 onMouseEnter={() => r.link && setLinkedAction(r.link)}
 style={{ outline: r.link && linkedAction === r.link ? "1.5px solid var(--ci-cyan)" : "none" }}>
 <span className={`cc-risk__sev cc-sev--${r.sev}`}>{r.sev}</span>
 <div className="cc-risk__body">
 <div className="cc-risk__subj">{r.subject}</div>
 <div className="cc-risk__meta">{r.issue} · {r.age} · {r.owner}</div>
 </div>
 <span className="ci-faint" style={{ fontSize: 10.5, whiteSpace: "nowrap" }}>{r.link ? "linked ↗" : r.next + " →"}</span>
 </div>
 ))}
 </div>
 <div style={{ flex: 1, minWidth: 0, borderLeft: "1px solid var(--ci-border)", paddingLeft: 14 }}>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Risk Exposure</div>
 <RiskMatrix items={RISKS.map(r => ({ x: r.x, y: r.y, label: r.subject, count: r.count }))} />
 </div>
 </div>
 </Panel>
 );
}

const NEXT: Record<string, string> = { NEW: "ASSIGNED", ASSIGNED: "IN PROGRESS", "IN PROGRESS": "COMPLETED", COMPLETED: "COMPLETED" };
const stateClass = (s: string) => "cc-state cc-state--" + s.replace(/\s/g, "");

export function ActionCenterRow() {
 const { toast, linkedAction } = useCmd();
 const [items, setItems] = React.useState<ActionItemX[]>(PRIORITY_ACTIONS);
 const advance = (id: string) => setItems(it => it.map(a => {
 if (a.id !== id) return a;
 const ns = NEXT[a.state]; toast(`${a.title} → ${ns}`); return { ...a, state: ns };
 }));
 const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
 return (
 <Panel span={5} hover title="Priority Actions" sub="What we are doing about it · advance to change state">
 <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
 {items.map(a => {
 const linked = linkedAction === a.id;
 return (
 <div key={a.id} className="cc-act"
 style={linked ? { borderColor: "var(--ci-cyan)", background: "var(--ci-cyan-soft)", boxShadow: "var(--ci-shadow-soft)" } : undefined}>
 <span className="ci-dot" style={{ background: SC[a.pri], boxShadow: `0 0 6px ${SC[a.pri]}`, flex: "none" }} />
 <div className="cc-act__body">
 <div className="cc-act__title">{a.title}</div>
 <div className="cc-act__meta">{a.cohort} · {a.owner} · due {a.due}</div>
 </div>
 <span className={stateClass(a.state)}>{a.state}</span>
 <Button size="sm" variant={linked ? "primary" : "ghost"}
 onClick={() => advance(a.id)}>{a.state === "NEW" ? "Assign" : a.state === "ASSIGNED" ? "Start" : a.state === "IN PROGRESS" ? "Complete" : "Open"}</Button>
 </div>
 );
 })}
 </div>
 </Panel>
 );
}
