 localPct: number; nationalPct: number; globalGap: number; velocity: number; stage: string; source: string;
}
const CN = [
 ["Faisal Al-Harbi", "Athletics", "Makkah", 18, 99, 96, -8, 88, "High Potential", "Schools"],
 ["Yousef Al-Otaibi", "Athletics", "Riyadh", 19, 97, 93, -12, 79, "High Potential", "Clubs"],
