 ["Layla Al-Harthi", "Fencing", "Eastern Province", 19, 88, 83, -17, 74, "Amateur", "Clubs"],
 ["Omar Al-Balawi", "Taekwondo", "Najran", 16, 87, 82, -19, 82, "Youth", "Coaches / PE"],
 ["Hind Al-Subaie", "Cycling", "Al Baha", 22, 86, 81, -15, 71, "Development", "Competitions"],
 ["Bandar Al-Dawsari", "Weightlifting", "Al Jouf", 23, 85, 80, -13, 65, "Amateur", "Federations"],
 ["Jood Al-Rashid", "Athletics", "Madinah", 15, 84, 79, -20, 78, "Youth", "Schools"],
];
export const COHORT: CohortAthlete[] = CN.map((c, i) => ({
 id: "C" + i, name: c[0] as string, sport: c[1] as string, region: c[2] as string, age: c[3] as number,
 localPct: c[4] as number, nationalPct: c[5] as number, globalGap: c[6] as number, velocity: c[7] as number,
 stage: c[8] as string, source: c[9] as string,
}));

// ---- Talent action queue ----
export interface TalentAction { id: string; title: string; pri: Status; cohort: string; owner: string; state: string; region?: string; }
export const TALENT_ACTIONS: TalentAction[] = [
 { id: "TA1", title: "Assess high-velocity cohort", pri: "cyan", cohort: "17 athletes", owner: "Talent ID", state: "NEW" },
 { id: "TA2", title: "Launch Makkah assessment campaign", pri: "amber", cohort: "Makkah region", owner: "Regional Lead", state: "NEW", region: "makkah" },
 { id: "TA3", title: "Schedule cross-sport assessments", pri: "cyan", cohort: "32 athletes", owner: "Performance", state: "ASSIGNED" },
 { id: "TA4", title: "Validate self-nominated athletes", pri: "green", cohort: "48 profiles", owner: "Operations", state: "IN PROGRESS" },
 { id: "TA5", title: "Add top-3 sprinters to watchlist", pri: "green", cohort: "3 athletes", owner: "Scouting", state: "NEW" },
 { id: "TA6", title: "Review under-assessed Jazan region", pri: "amber", cohort: "Jazan region", owner: "Regional Lead", state: "NEW", region: "jazan" },
];

// ---- Region-derived opportunity metrics ----
const avgDiscovered = REGIONS_T.reduce((s, r) => s + r.discovered, 0) / REGIONS_T.length;
export function regionDerived(r: RegionT) {
 const coverage = Math.round((r.assessed / r.discovered) * 100);
 const participationIdx = Math.round((r.discovered / avgDiscovered) * 100);
 const opportunity = Math.max(0, Math.min(100, Math.round(
 (participationIdx / 100) * 34 +
 Math.max(0, NATIONAL_CONVERSION_AVG - r.conversion) * 6 +
 Math.max(0, 55 - coverage) * 0.7
 )));
 return { coverage, participationIdx, participationVsAvg: participationIdx - 100, opportunity };
}
export function highestOpportunityRegion() {
 return [...REGIONS_T].sort((a, b) => regionDerived(b).opportunity - regionDerived(a).opportunity)[0].key;
}

export { REGIONS_T, NATIONAL_CONVERSION_AVG };
