const PRI: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const LANES = [
 { key: "red", label: "Critical", icon: "alert" as const },
 { key: "amber", label: "Attention", icon: "flag" as const },
 { key: "cyan", label: "Opportunity", icon: "star" as const },
 { key: "green", label: "On Track", icon: "activity" as const },
];
const EXTRA = [
 { id: "a6", title: "Coastal swimming surge — allocate scouting capacity", meta: "+34% identification · resourcing", pri: "cyan", type: "Investigate" },
 { id: "a7", title: "Nadia Petrov — recovery trending down 3 weeks", meta: "Recovery 58% · Cycling · North", pri: "amber", type: "Assign Specialist" },
 { id: "a8", title: "Sofia Andersen — confirm podium pathway placement", meta: "Percentile 96 · Gymnastics", pri: "green", type: "Track Outcome" },
];

export function Actions() {
 const { toast } = useApp();
 const all = [...ACTION_QUEUE, ...EXTRA];
 return (
 <div className="ci-fade">
 <PageHead title="Actions" desc="Every insight connects to a next best action. Prioritized, assignable and tracked to outcome — no passive dashboards."
 actions={<Button icon="plus" variant="primary" onClick={() => toast("New intervention created")}>Create Intervention</Button>} />

 <div className="ci-grid">
 {LANES.map(lane => {
 const items = all.filter(a => a.pri === lane.key);
 const I = Icon[lane.icon];
 return (
 <Panel key={lane.key} span={3} hover title={lane.label}
 right={<span className="ci-chip ci-chip--ghost">{items.length}</span>}>
 <div className="ci-actions-list">
 {items.length === 0 && <div className="ci-faint" style={{ fontSize: 12, padding: "10px 2px" }}>Nothing here — all clear.</div>}
 {items.map(a => (
 <div className="ci-action" key={a.id} style={{ flexDirection: "column", alignItems: "stretch", gap: 8 }}>
 <div style={{ display: "flex", gap: 10 }}>
 <span style={{ color: PRI[lane.key], flex: "none" }}><I style={{ width: 15, height: 15 }} /></span>
 <div className="ci-action__body">
 <div className="ci-action__title" style={{ fontSize: 12 }}>{a.title}</div>
 <div className="ci-action__meta">{a.meta}</div>
 </div>
 </div>
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
 <Chip status={a.pri as any}>{a.type}</Chip>
 <Button size="sm" variant="ghost" onClick={() => toast(`${a.type} actioned`)}>Act</Button>
 </div>
 </div>
 ))}
 </div>
 </Panel>
 );
 })}
 </div>
 </div>
 );
}
